function hasLedgerKey(key){return !!state.economy?.ledger?.some(x=>x.key===key)}
function ledgerChange(delta,reason,key,save=true){ensureEconomyBare();if(key&&hasLedgerKey(key))return false;const before=state.economy.coins;const actual=delta<0?-Math.min(before,Math.abs(delta)):delta;state.economy.coins=Math.max(0,before+actual);if(actual>0)state.economy.lifetimeEarned=(state.economy.lifetimeEarned||0)+actual;if(actual<0)state.economy.lifetimeSpent=(state.economy.lifetimeSpent||0)+Math.abs(actual);state.economy.ledger.unshift({id:crypto.randomUUID(),key:key||crypto.randomUUID(),delta:actual,reason,at:new Date().toISOString()});state.economy.ledger=state.economy.ledger.slice(0,200);if(save)localStorage.setItem(storeKey,JSON.stringify(state));return actual}
function ensureEconomyBare(){state.economy=state.economy||{coins:0,lifetimeEarned:0,lifetimeSpent:0,ledger:[],ownedThemes:['eclipse'],welcomeGift:false};state.economy.ledger=state.economy.ledger||[];state.economy.ownedThemes=state.economy.ownedThemes||['eclipse'];state.economy.coins=Number(state.economy.coins)||0}
function spendCoins(cost,reason,key){ensureEconomyBare();if(state.economy.coins<cost){toast(`Necesitás ${cost-state.economy.coins} monedas más.`,'warn');return false}ledgerChange(-cost,reason,key);syncHeaderStatus();return true}

// ---------- Audio: persistent, resumable and user-controlled ----------
const soundPrefKey='vidaRpgSoundV7';
window.VIDA_SOUND=(()=>{let ctx=null,ambientGain=null,ambientNodes=[];const enabled=()=>localStorage.getItem(soundPrefKey)!=='off';async function ensure(){const A=window.AudioContext||window.webkitAudioContext;if(!A)return null;if(!ctx)ctx=new A();if(ctx.state==='suspended'){try{await ctx.resume()}catch(e){}}return ctx}function update(){const on=enabled();document.querySelectorAll('#soundToggle,#globalSoundToggle').forEach(b=>b.textContent=on?'🔊':'🔇');if(state?.rpg)state.rpg.sound=on}async function startAmbient(){if(!enabled())return;const c=await ensure();if(!c)return;if(!ambientGain){ambientGain=c.createGain();ambientGain.gain.value=.0001;ambientGain.connect(c.destination);[55,82.4,110].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type=i===1?'triangle':'sine';o.frequency.value=f;g.gain.value=i===0?.7:.24;o.connect(g).connect(ambientGain);o.start();ambientNodes.push(o)});}const now=c.currentTime;ambientGain.gain.cancelScheduledValues(now);ambientGain.gain.setValueAtTime(Math.max(.0001,ambientGain.gain.value||.0001),now);ambientGain.gain.exponentialRampToValueAtTime(.018,now+.18);update()}async function stopAmbient(){if(!ctx||!ambientGain)return;const now=ctx.currentTime;ambientGain.gain.cancelScheduledValues(now);ambientGain.gain.setValueAtTime(Math.max(.0001,ambientGain.gain.value||.0001),now);ambientGain.gain.exponentialRampToValueAtTime(.0001,now+.12)}async function set(on){localStorage.setItem(soundPrefKey,on?'on':'off');if(state?.rpg){state.rpg.sound=on;localStorage.setItem(storeKey,JSON.stringify(state))}if(on){await ensure();if(page==='assessment'||page==='combat')await startAmbient();await play('click')}else{await stopAmbient();if(ctx?.state==='running'){setTimeout(()=>ctx?.suspend().catch(()=>{}),150)}}update();return on}async function toggle(){return set(!enabled())}async function play(type='click'){if(!enabled())return;const c=await ensure();if(!c)return;const o=c.createOscillator(),g=c.createGain(),now=c.currentTime;o.connect(g);g.connect(c.destination);o.type=type==='level'?'triangle':type==='penalty'?'sawtooth':'sine';const f=type==='reward'?650:type==='level'?420:type==='penalty'?120:300;o.frequency.setValueAtTime(f,now);if(type==='level')o.frequency.exponentialRampToValueAtTime(920,now+.45);if(type==='penalty')o.frequency.exponentialRampToValueAtTime(70,now+.35);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(type==='penalty'?.045:.07,now+.015);g.gain.exponentialRampToValueAtTime(.0001,now+(type==='level'?.65:type==='penalty'?.45:.18));o.start();o.stop(now+(type==='level'?.7:type==='penalty'?.5:.2))}return{enabled,startAmbient,stopAmbient,set,toggle,play,update}})();

function injectHeaderStatus(){if(page==='assessment')return;const top=document.querySelector('.topbar');if(!top||document.querySelector('.topbar-status'))return;const box=document.createElement('div');box.className='topbar-status';box.innerHTML='<a id="headerCoins" class="coin-pill" href="tienda.html">🪙 <strong>0</strong></a><button id="globalSoundToggle" class="sound-mini" aria-label="Sonido">🔊</button>';const nav=top.querySelector('.desktop-nav');top.insertBefore(box,nav||null);box.querySelector('#globalSoundToggle').addEventListener('click',()=>window.VIDA_SOUND.toggle())}
