function relevantSkills(profile){const arr=[bottleneckSkill[profile.bottleneck]].filter(Boolean);(profile.responsibilities||[]).forEach(r=>arr.push(...(responsibilitySkills[r]||[])));const weak=[...allSkills].sort((a,b)=>effectiveSkillData()[a].score-effectiveSkillData()[b].score);arr.push(...weak);return [...new Set(arr)].filter(Boolean)}
function generatePlan(profile){const focus=relevantSkills(profile).slice(0,3);state.improvementPlan.profile=profile;state.improvementPlan.focusSkills=focus;state.improvementPlan.questionnaireComplete=true;state.improvementPlan.startedAt=todayKey();state.improvementPlan.updatedAt=new Date().toISOString();state.improvementPlan.cycleStart=todayKey();state.improvementPlan.cycleLength=30;state.improvementPlan.acceptedDays={};state.improvementPlan.protectedDays={};removeUnfinishedLegacyTasks();localStorage.setItem(storeKey,JSON.stringify(state));return focus}
function removeUnfinishedLegacyTasks(){const legacy=new Set(['Definir 3 prioridades del día','Registrar o revisar un movimiento financiero','Cumplir la actividad física planificada','Resolver o avanzar un problema importante','Aclarar o coordinar algo con un compañero','Aclarar o coordinar algo con un compañero de estudio']);const d=state.days[todayKey()];if(d)d.tasks=(d.tasks||[]).filter(t=>t.done||t.custom||!legacy.has(t.text))}
