function cycleDayNumber(){if(!state.improvementPlan.cycleStart)return 1;return Math.max(1,Math.floor((new Date(todayKey()+'T12:00:00')-new Date(state.improvementPlan.cycleStart+'T12:00:00'))/86400000)+1)}
function chooseResponsibility(profile,k){const rs=profile.responsibilities||[];if(!rs.length)return profile.area==='finance'?'finance':profile.area==='sales'?'sales':profile.area==='education'?'study':['construction','industrial','fieldwork'].includes(profile.area)?'physical':profile.area==='warehouse'?'warehouse':profile.area==='transport'?'transport':profile.area==='maintenance'?'maintenance':'operations';return rs[seededHash(k)%rs.length]}
