function syncEconomyRewards(){ensureEconomyBare();Object.entries(state.missions?.daily||{}).forEach(([date,d])=>(d.items||[]).forEach(m=>{if(m.done)ledgerChange(2,`Misión del Sistema · ${m.skill}`,`coin-mission:${m.id}`,false)}));Object.entries(state.missions?.chests||{}).forEach(([date,c])=>{if(c.claimed)ledgerChange(10,'Cofre diario',`coin-chest:${date}`,false)});Object.entries(state.missions?.weekly||{}).forEach(([wk,b])=>{if(b.claimed)ledgerChange(25,`Boss semanal · ${b.attr||''}`,`coin-boss:${wk}`,false)});Object.entries(state.academyCertifications||{}).forEach(([cat,c])=>{if(c.passed)ledgerChange(20,`Certificación · ${cat}`,`coin-cert:${cat}`,false)});settleCompletedPlanDaysNoLoop();localStorage.setItem(storeKey,JSON.stringify(state))}
function settleCompletedPlanDaysNoLoop(){Object.entries(state.days||{}).forEach(([date,d])=>{const tasks=(d.tasks||[]).filter(t=>t.source==='plan');if(tasks.length&&tasks.every(t=>t.done)&&!hasLedgerKey(`plan-complete:${date}`))ledgerChange(8,'Plan diario completado',`plan-complete:${date}`,false)})}
function buyExtraLesson(){if(!spendCoins(25,'Llave de Academia'))return false;state.monetization.bonusLessons[todayKey()]=(state.monetization.bonusLessons[todayKey()]||0)+1;localStorage.setItem(storeKey,JSON.stringify(state));toast('Llave comprada · +1 lección hoy','good');return true}
function buyShopItem(item){if(item==='lesson'){if(buyExtraLesson())renderStorePage();return}if(item==='shield'){if(!spendCoins(45,'Escudo de penalización'))return;state.penalties.shields++;localStorage.setItem(storeKey,JSON.stringify(state));toast('Escudo añadido al inventario.','good')}else if(item==='reroll'){const daily=state.missions?.daily?.[todayKey()];if(daily?.items?.some(x=>x.done))return toast('No podés recalibrar después de completar una misión hoy.','warn');if(!spendCoins(20,'Recalibrar misiones'))return;delete state.missions.daily[todayKey()];localStorage.setItem(storeKey,JSON.stringify(state));toast('Las Misiones del Sistema fueron recalibradas.','good')}else if(item.startsWith('theme:')){const id=item.split(':')[1],def=themeDefs[id];if(themeOwned(id)){state.rpg.theme=id;localStorage.setItem(storeKey,JSON.stringify(state));applyTheme();toast(`Tema ${def.name} equipado.`,'good')}else{if(!spendCoins(def.price,`Tema ${def.name}`))return;state.economy.ownedThemes.push(id);state.rpg.theme=id;localStorage.setItem(storeKey,JSON.stringify(state));applyTheme();toast(`Tema ${def.name} desbloqueado.`,'good')}}renderStorePage();syncHeaderStatus()}
async function buyCoinPack(packId){const m=$('#coinPurchaseMessage');try{if(!window.VIDA_RPG_COIN_PURCHASE?.buy)throw new Error('Todavía no hay un proveedor de pago seguro conectado.');m.className='quiz-feedback';m.textContent='Esperando confirmación del proveedor...';const r=await window.VIDA_RPG_COIN_PURCHASE.buy(packId);if(!r?.verified||!r.transactionId||!Number(r.coins))throw new Error('El servidor no confirmó la compra.');ledgerChange(Number(r.coins),'Compra de monedas',`real-money:${r.transactionId}`);m.className='quiz-feedback good';m.textContent=`Compra verificada · +${r.coins} monedas.`;renderStorePage()}catch(e){m.className='quiz-feedback bad';m.textContent=e.message}}
function renderStorePage(){if(page!=='store')return;syncEconomyRewards();$('#storeCoins').textContent=state.economy.coins;$$('[data-shop-item]').forEach(b=>{const item=b.dataset.shopItem;if(item.startsWith('theme:')){const id=item.split(':')[1];b.textContent=themeOwned(id)?(state.rpg.theme===id?'Equipado':'Equipar'):'Desbloquear'}});$('#coinLedger').innerHTML=state.economy.ledger.slice(0,16).map(x=>`<div class="ledger-row"><div><strong>${escapeHtml(x.reason)}</strong><small>${new Date(x.at).toLocaleString('es-AR')}</small></div><span class="${x.delta>=0?'coin-plus':'coin-minus'}">${x.delta>=0?'+':''}${x.delta} 🪙</span></div>`).join('')||'<div class="empty">Sin movimientos.</div>'}

